<div class="topic-shell space-y-5" data-topic-batch><div class="flex flex-wrap justify-between gap-3"><div><h1 class="text-2xl font-semibold">批次 #{{ $batch->id }}</h1><p class="topic-help mt-2">{{ $sites[$site]??$site }} · {{ count($batch->rows) }} 个标题 · {{ $labels[$batch->status]??$batch->status }}</p></div><a class="topic-button" href="{{ route('admin.topics.index',['site'=>$site]) }}">返回专题列表</a></div><section class="topic-panel"><dl class="flex flex-wrap gap-4 mb-4">@foreach($batchData['current_counts'] as $key=>$count)<div><dt class="topic-help">{{ $stateLabels[$key]??$key }}</dt><dd class="text-lg font-semibold">{{ $count }} 个专题</dd></div>@endforeach</dl><dl class="flex flex-wrap gap-4 mb-4">@foreach($batchData['counts'] as $key=>$count)<div><dt class="topic-help">{{ $labels[$key]??$key }}</dt><dd class="text-lg font-semibold">{{ $count }} 项</dd></div>@endforeach</dl><div class="flex flex-wrap gap-2">@if(in_array($batch->status,['pending','running']))<form method="POST" action="{{ route('admin.topics.batches.action',['batch'=>$batch->id,'action'=>'cancel']) }}">@csrf<button class="topic-button">取消剩余执行</button></form>@endif @if($batchData['can_retry'])<form method="POST" action="{{ route('admin.topics.batches.action',['batch'=>$batch->id,'action'=>'retry']) }}">@csrf<button class="topic-button">{{ collect($batchData['rows'])->contains('lease_expired',true)?'恢复中断项并重试失败项':'仅重试失败项' }}</button></form>@endif @if($batch->status==='cancelled')<form method="POST" action="{{ route('admin.topics.batches.action',['batch'=>$batch->id,'action'=>'continue']) }}">@csrf<button class="topic-button topic-primary">继续剩余项</button></form>@endif</div><p class="topic-help mt-3">已完成的结果继续保留；重试与继续使用本批原配置。</p><p class="topic-help" data-batch-status></p></section><div class="overflow-x-auto bg-white border border-gray-200 rounded-lg"><table><thead><tr><th>行</th><th>标题</th><th>状态</th><th>专题 / 生成记录</th><th>详情</th></tr></thead><tbody>@foreach($batchData['rows'] as $row)<tr id="batch-row-{{ $row['number'] }}"><td>{{ $row['number'] }}</td><td>{{ $row['title'] }}</td><td>{{ $labels[$row['status']]??$row['status'] }}@if($row['current_state'])<p class="topic-help mt-1">专题当前：{{ $stateLabels[$row['current_state']]??$row['current_state'] }}</p>@endif</td><td><div class="space-y-1">@if($row['topic_id'])<a class="text-blue-600 block" href="{{ $row['topic_url'] }}">专题 #{{ $row['topic_id'] }}</a>@endif @if($row['run_id'])<a class="text-blue-600 block" href="{{ route('admin.topics.runs.show',['run'=>$row['run_id']]) }}">生成 #{{ $row['run_id'] }}</a>@endif @if($row['duplicate_of'])<a class="text-blue-600 block" href="#batch-row-{{ $row['duplicate_of'] }}">首条：第 {{ $row['duplicate_of'] }} 行</a>@endif</div></td><td class="text-sm text-red-700">{{ $row['error'] }}@if($row['lease_expired'])<p class="topic-help">执行中断，可恢复已保存结果。</p>@endif @if($row['can_retry']&&$batchData['can_retry'])<form method="POST" action="{{ route('admin.topics.batches.action',['batch'=>$batch->id,'action'=>'retry']) }}" class="mt-2">@csrf<input type="hidden" name="row_numbers[]" value="{{ $row['number'] }}"><button class="topic-button">{{ $row['lease_expired']?'恢复此项':'重试此项' }}</button></form>@endif</td></tr>@endforeach</tbody></table></div></div>
<script>(()=>{let timer;async function poll(){try{const r=await fetch(@json(route('admin.topics.batches.status',['batch'=>$batch->id])),{headers:{Accept:'application/json'}});if(!r.ok)throw Error();const d=await r.json();if(JSON.stringify(d.rows)!==JSON.stringify(@json($batchData['rows']))||d.status!==@json($batch->status)){location.reload();return;}timer=setTimeout(poll,3000);}catch{document.querySelector('[data-batch-status]').textContent='暂时无法获取批次状态，请刷新页面。';}}if(@json(in_array($batch->status,['pending','running'])))timer=setTimeout(poll,3000);window.addEventListener('pagehide',()=>clearTimeout(timer));})();</script>
